//! Address equations of the gfx11 swizzle modes that host-layout surface copies use, for the host
//! GPU's addressing configuration (GB_ADDR_CONFIG 0x343: 8 pipes, 8 packers, 256-byte interleave).
//! Same encoding as the guest tables: per byte-address bit inside a block, the element-coordinate
//! bits XORed into it, x bits in bits 0-11, y bits in 12-23 and array-layer bits in 24-31.
//!
//! Generated by `driver/tools/surface-tables/generate.py --gb-addr-config 0x343`
//! from AMD's address library in Mesa (lfrb/mesa wddm2 801c9763, `src/amd/addrlib`, MIT; see
//! THIRD_PARTY_NOTICES.txt). Do not edit by hand.

/// One equation per element size: 1, 2, 4, 8 and 16 bytes.
type Equations = [[u32; 16]; 5];

/// The equation of a thin (2D) host swizzle mode; all-zero rows are element sizes the mode lacks.
pub(super) fn equation(mode: u32, element_log2: u32) -> Option<&'static [u32; 16]> {
    let equations = match mode {
        2 => &SW_256B_D,
        6 => &SW_4KB_D,
        10 => &SW_64KB_D,
        18 => &SW_64KB_D_T,
        22 => &SW_4KB_D_X,
        24 => &SW_64KB_Z_X,
        26 => &SW_64KB_D_X,
        27 => &SW_64KB_R_X,
        _ => return None,
    };
    equations
        .get(element_log2 as usize)
        .filter(|equation| equation.iter().any(|&mask| mask != 0))
}

